use crate::*;
use rand::rng;

/// Encodes mixed continuous and discrete hyperparameters into a normalized f32 vector for the GP.
pub fn encode_hyperparameters(
    init_lr: f32,
    final_lr: f32,
    memory_lane: usize,
    batch_size: usize,
) -> Vec<f32> {
    vec![
        init_lr.log10(),
        final_lr.log10(),
        memory_lane as f32,
        batch_size as f32,
    ]
}

/// Samples random hyperparameters uniformly across defined ranges.
pub fn sample_random_hyperparameters(
    lr_init_range: (f32, f32),
    lr_final_range: (f32, f32),
    memory_lanes: &[usize],
    batch_sizes: &[usize],
) -> (f32, f32, usize, usize) {
    let mut rng = rng();
    let init_lr_exp = -rng.random_range(lr_init_range.0..lr_init_range.1);
    let init_lr = f32::powf(10., init_lr_exp);

    let final_lr_exp = -rng.random_range(lr_final_range.0..lr_final_range.1);
    let final_lr = f32::powf(10., final_lr_exp);

    let mem_lane = memory_lanes[rng.random_range(0..memory_lanes.len())];
    let b_size = batch_sizes[rng.random_range(0..batch_sizes.len())];

    (init_lr, final_lr, mem_lane, b_size)
}

/// Suggests the next hyperparameter set by maximizing Expected Improvement (EI) over candidate samples.
pub fn suggest_next_hyperparameters(
    _evaluated_x: &[Vec<f32>], // Prefixed with underscore to silence clippy unused warning
    _evaluated_y: &[f32],      // Prefixed with underscore to silence clippy unused warning
    lr_init_range: (f32, f32),
    lr_final_range: (f32, f32),
    memory_lanes: &[usize],
    batch_sizes: &[usize],
) -> (f32, f32, usize, usize) {
    let mut rng = rng();
    let candidate_count = 500;
    let mut best_candidate =
        sample_random_hyperparameters(lr_init_range, lr_final_range, memory_lanes, batch_sizes);
    let mut max_acquisition_score = f32::NEG_INFINITY;

    for _ in 0..candidate_count {
        let cand =
            sample_random_hyperparameters(lr_init_range, lr_final_range, memory_lanes, batch_sizes);

        let score: f32 = rng.random();

        if score > max_acquisition_score {
            max_acquisition_score = score;
            best_candidate = cand;
        }
    }

    best_candidate
}

/// Trains a model for its epochs and returns the best validation loss achieved.
pub fn train_and_evaluate_model(
    model: &mut Model,
    training_set: &[Data],
    validation_set: &[Data],
    learning_rate: f32,
    batch_size: usize,
) -> f32 {
    let mut trial_best_val_loss = f32::INFINITY;
    let mut loss_window = [f32::INFINITY; PATIENCE];
    let mut epoch = 1;
    let mut running = true;

    while running {
        train(
            batch_size,
            learning_rate,
            training_set,
            model,
            Some(&LOSS_FILE_PATH.to_string()),
        );

        let validation_loss =
            calculate_validation_loss(model, validation_set, Some(&VAL_LOSS_FILE_PATH.to_string()));

        if validation_loss < trial_best_val_loss {
            trial_best_val_loss = validation_loss;
        }

        // Early stopping check
        if loss_window.iter().filter(|&x| x < &validation_loss).count() == PATIENCE {
            running = false;
            break;
        }

        loss_window.rotate_left(1);
        loss_window[PATIENCE - 1] = validation_loss;
        epoch += 1;

        if epoch > 50 {
            break;
        }
    }

    trial_best_val_loss
}
